package org.example.ui;
import org.example.dao.TaskDao; import org.example.dao.UserDao; import org.example.model.User; import java.sql.SQLException; import java.util.Scanner;
public class ManagerMenu {private final Scanner scanner;private final User user;private final UserDao userDao;private final TaskDao taskDao;public ManagerMenu(Scanner s,User u,UserDao ud,TaskDao td){scanner=s;user=u;userDao=ud;taskDao=td;}public void start(){boolean run=true;while(run){System.out.println("\n========== TASKPILOT MANAGER ==========");System.out.println("Logged in as: "+user.username());System.out.println("1. Create and assign task\n2. View all tasks\n3. Task progress and deadline report\n4. Cancel task\n0. Logout");System.out.print("Choose: ");switch(scanner.nextLine().trim()){case "1"->create();case "2"->view();case "3"->report();case "4"->cancel();case "0"->run=false;default->System.out.println("Invalid choice.");}}}private void create(){try{var employees=userDao.getEmployees();if(employees.isEmpty()){System.out.println("No approved employees yet. Ask an admin to approve an employee account.");return;}System.out.println("Approved employees:");for(User e:employees)System.out.printf("ID: %d | %s%n",e.id(),e.username());System.out.print("Task name: ");String name=scanner.nextLine().trim();if(name.isEmpty()){System.out.println("Task name is required.");return;}System.out.print("Description: ");String desc=scanner.nextLine().trim();int emp=readInt("Employee ID (0 for unassigned): ");if(emp!=0&&employees.stream().noneMatch(e->e.id()==emp)){System.out.println("That ID is not an approved employee.");return;}System.out.print("Priority (LOW/MEDIUM/HIGH): ");String priority=scanner.nextLine().trim().toUpperCase();if(!java.util.Set.of("LOW","MEDIUM","HIGH").contains(priority)){System.out.println("Invalid priority.");return;}System.out.print("Start date (YYYY-MM-DD): ");String start=scanner.nextLine().trim();System.out.print("Due date (YYYY-MM-DD): ");String due=scanner.nextLine().trim();if(!start.matches("\\d{4}-\\d{2}-\\d{2}")||!due.matches("\\d{4}-\\d{2}-\\d{2}")){System.out.println("Dates must use YYYY-MM-DD.");return;}System.out.println(taskDao.createTask(name,desc,emp,priority,start,due,user.id())?"Task created successfully.":"Task was not created.");}catch(SQLException e){System.out.println("Could not create task: "+e.getMessage());}}private int readInt(String p){while(true){System.out.print(p);try{return Integer.parseInt(scanner.nextLine().trim());}catch(NumberFormatException e){System.out.println("Enter a whole number.");}}}private void view(){try{var ts=taskDao.getAllTasks();for(var t:ts)System.out.printf("#%d | %s | %s | %s | due %s | %s | employee: %s%n",t.id(),t.name(),t.priority(),t.status(),t.dueDate(),t.progressNotes(),t.employeeName());if(ts.isEmpty())System.out.println("No tasks yet.");}catch(SQLException e){System.out.println("Could not retrieve tasks: "+e.getMessage());}}private void report(){try{int[]a=taskDao.getSummary();System.out.printf("Total: %d | Completed: %d | Pending: %d | Ongoing: %d | Overdue: %d | High priority: %d%n",a[0],a[1],a[2],a[3],a[4],a[5]);}catch(SQLException e){System.out.println("Report failed: "+e.getMessage());}}private void cancel(){view();int id=readInt("Task ID to cancel (0 to back): ");if(id==0)return;try{System.out.println(taskDao.cancelTask(id)?"Task cancelled.":"Task not found.");}catch(SQLException e){System.out.println("Could not cancel: "+e.getMessage());}}}
